# Run once on a remote machine, or reuse a session for several calls
Invoke-Command -ComputerName web01 -ScriptBlock { Get-Service Spooler }
$session = New-PSSession -ComputerName web01 -Credential (Get-Credential)
Invoke-Command -Session $session -ScriptBlock { Get-WinEvent -LogName System -MaxEvents 5 }
Remove-PSSession $session

# Fail loudly instead of continuing after an error
$ErrorActionPreference = 'Stop'
try {
  Copy-Item .\a.txt D:\b.txt -ErrorAction Stop
} catch {
  Write-Error $_.Exception.Message
}
